s='NY:SSL 145-B'
add([{'section_id': s, 'decision': 'new_rule', 'reason': 'Makes a knowingly false claim to a social services district (for example an inflated damage or rent claim on an HRA security voucher, or keeping shelter payments for months the household was gone) liable for treble damages or $5,000.', 'proposed': [rule(s, instrument='NY Social Services Law',
  id='NY:SSL-145-b-false-claims', provision='SSL 145-b(1)-(2)', actor='landlord, managing agent, Handoff', modality='liability',
  determinacy='MIXED', judgment_terms=['knowingly', 'false statement or representation', 'deliberate concealment of any material fact'],
  condition='The landlord or its agent seeks or obtains payment from a social services district for housing furnished to a public-assistance household: a claim on a security voucher or agreement (NYC:HRA-voucher-claim-window), a claim under a housing allowance, or direct shelter payments; and the claim or a statement supporting it is knowingly false or conceals a material fact (for example damage the tenant did not cause, rent for months after the household left, or failure to disclose payments already received).',
  effect='The district or the State may recover civil damages of three times the amount falsely overstated (or three times its damages for a non-monetary falsehood), or $5,000, whichever is greater. A claim for payment made to a political subdivision or its contractor is a statement for this purpose, and any payment funded in part by public money counts. Claims on vouchers therefore carry only the itemized, supported amounts the ordinary deposit rules would allow (NY:GOL-7-108(1-a)(b)-refundable, NYC:HRA-voucher-proof).',
  dependencies=['NYC:HRA-voucher-claim-window', 'NYC:HRA-voucher-proof', 'NY:SSL-143-c-agency-deposit-refund'],
  quote=q(s, 'It shall be unlawful for any person, firm or corporation knowingly by means of a false statement or representation, or by deliberate concealment of any material fact, or other fraudulent scheme or device, on behalf of himself or others, to attempt to obtain or to obtain payment from public funds for services or supplies furnished or purportedly furnished pursuant to this chapter.'),
  construction=[{'source_file': 'register/texts/NY_SSL/145-b.txt', 'quote': q(s, 'three times the amount by which any figure is falsely overstated')}],
  reasoning='Housing furnished to a recipient under a security agreement (SSL 143-c) or shelter allowance (SSL 131-a) is furnished pursuant to the Social Services Law, and a claim for payment made to a social services district is a statement under 145-b(1)(b).',
  severity='critical', walk_step='5.8')]}])
